insert into public.categorias_productos(nombre,orden,publicado) select n,i,true from unnest(array['Cañas','Líneas y sedales','Carretes','Señuelos','Anzuelos','Accesorios','Almacenamiento','Ropa y protección','Mantenimiento']) with ordinality as x(n,i) on conflict(nombre) do nothing; insert into public.categorias_consejos(nombre,orden,publicado) select n,i,true from unnest(array['Nudos','Técnicas','Equipo','Conservación','Seguridad','Clima y mareas','Especies','Buenas prácticas']) with ordinality as x(n,i) on conflict(nombre) do nothing;;
